import javax.swing.*;import java.awt.*;
/** Lightweight Swing syllabus demonstration; production data management is in the web admin. */
public class ShopSphereAdminDemo {public static void main(String[] args){SwingUtilities.invokeLater(()->{try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(Exception ignored){}JFrame f=new JFrame("ShopSphere · Desktop Admin Demo");f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);f.setSize(650,400);f.setLocationRelativeTo(null);JPanel root=new JPanel(new BorderLayout(12,12));root.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));root.add(new JLabel("ShopSphere Inventory Overview",SwingConstants.CENTER),BorderLayout.NORTH);String[] cols={"Product ID","Product","Stock","Status"};Object[][] rows={{1,"Wireless Headphones",25,"Active"},{2,"Everyday Backpack",18,"Active"},{3,"Desk Lamp",30,"Active"}};root.add(new JScrollPane(new JTable(rows,cols)),BorderLayout.CENTER);JPanel actions=new JPanel();JTextField id=new JTextField(5);actions.add(new JLabel("Product ID:"));actions.add(id);actions.add(new JButton("Refresh demo"));root.add(actions,BorderLayout.SOUTH);f.setContentPane(root);f.setVisible(true);});}}
